@@ -0,0 +1,246 @@
+/*
+    SPDX-FileCopyrightText: 2026 Wensheng Tang <sp3478@gmail.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "canberrasoundplayer_p.h"
+#include "debug.h"
+
+#include <QElapsedTimer>
+#include <QFile>
+#include <QMap>
+#include <QMutex>
+#include <QPointer>
+#include <QRegularExpression>
+#include <QScopeGuard>
+#include <QSemaphore>
+#include <QTest>
+#include <QTimer>
+
+#include <atomic>
+#include <canberra.h>
+#include <memory>
+
+using namespace Qt::StringLiterals;
+using namespace NotificationManager;
+
+Q_LOGGING_CATEGORY(NOTIFICATIONMANAGER, "org.kde.plasma.notificationmanager")
+
+// Replace only the audio boundary: the production worker, queued delivery and
+// shutdown run unchanged, without wedging the user's real audio server.
+struct ca_context {
+    QThread *thread;
+};
+struct ca_proplist {
+    QMap<QByteArray, QByteArray> values;
+};
+
+namespace
+{
+struct {
+    std::atomic<int> created = 0;
+    std::atomic<int> destroyed = 0;
+    std::atomic<int> played = 0;
+    std::atomic<bool> failContext = false;
+    std::atomic<bool> failProperties = false;
+    std::atomic<bool> block = false;
+    std::atomic<bool> correctThread = true;
+    QSemaphore entered;
+    QSemaphore unblock;
+    QMutex mutex;
+    QMap<QByteArray, QByteArray> properties;
+    QThread *workerThread = nullptr;
+} backend;
+}
+
+int ca_context_create(ca_context **context)
+{
+    if (backend.failContext.exchange(false)) {
+        return CA_ERROR_OOM;
+    }
+    *context = new ca_context{QThread::currentThread()};
+    backend.workerThread = QThread::currentThread();
+    backend.correctThread = backend.correctThread && QThread::currentThread() != QCoreApplication::instance()->thread();
+    ++backend.created;
+    return CA_SUCCESS;
+}
+
+int ca_context_destroy(ca_context *context)
+{
+    backend.correctThread = backend.correctThread && QThread::currentThread() == context->thread;
+    delete context;
+    ++backend.destroyed;
+    return CA_SUCCESS;
+}
+
+int ca_proplist_create(ca_proplist **properties)
+{
+    if (backend.failProperties.exchange(false)) {
+        return CA_ERROR_OOM;
+    }
+    *properties = new ca_proplist;
+    return CA_SUCCESS;
+}
+
+int ca_proplist_destroy(ca_proplist *properties)
+{
+    delete properties;
+    return CA_SUCCESS;
+}
+
+int ca_proplist_sets(ca_proplist *properties, const char *key, const char *value)
+{
+    properties->values.insert(key, value);
+    return CA_SUCCESS;
+}
+
+int ca_context_play_full(ca_context *context, uint32_t, ca_proplist *properties, ca_finish_callback_t, void *)
+{
+    backend.correctThread = backend.correctThread && QThread::currentThread() == context->thread;
+    {
+        QMutexLocker locker(&backend.mutex);
+        backend.properties = properties->values;
+    }
+    ++backend.played;
+    backend.entered.release();
+    if (backend.block) {
+        backend.unblock.acquire();
+    }
+    return CA_SUCCESS;
+}
+
+const char *ca_strerror(int)
+{
+    return "fake audio error";
+}
+
+class CanberraSoundPlayerTest : public QObject
+{
+    Q_OBJECT
+private Q_SLOTS:
+    void init()
+    {
+        backend.created = 0;
+        backend.destroyed = 0;
+        backend.played = 0;
+        backend.failContext = false;
+        backend.failProperties = false;
+        backend.block = false;
+        backend.correctThread = true;
+        backend.workerThread = nullptr;
+        backend.entered.tryAcquire(backend.entered.available());
+        backend.unblock.tryAcquire(backend.unblock.available());
+        backend.properties.clear();
+    }
+
+    void preservesSoundProperties_data()
+    {
+        QTest::addColumn<QString>("soundName");
+        QTest::addColumn<QString>("soundFilePath");
+        QTest::newRow("theme sound") << u"message-new-instant"_s << QString();
+        QTest::newRow("sound file") << QString() << u"/tmp/通知.oga"_s;
+        QTest::newRow("both hints") << u"message-new-instant"_s << u"/tmp/通知.oga"_s;
+    }
+
+    void preservesSoundProperties()
+    {
+        QFETCH(QString, soundName);
+        QFETCH(QString, soundFilePath);
+        QPointer<QThread> thread;
+        {
+            QObject parent;
+            CanberraSoundPlayer player(&parent);
+            QCOMPARE(player.thread(), QThread::currentThread());
+            const CanberraSoundRequest request{soundName, soundFilePath, u"Test App"_s, u"org.kde.test"_s, u"ocean"_s};
+            player.play(request);
+            QVERIFY(backend.entered.tryAcquire(1, 5000));
+            thread = backend.workerThread;
+            QMap<QByteArray, QByteArray> properties;
+            {
+                QMutexLocker locker(&backend.mutex);
+                properties = backend.properties;
+            }
+            QCOMPARE(properties.value(CA_PROP_EVENT_ID), soundName.toLatin1());
+            QCOMPARE(properties.value(CA_PROP_MEDIA_FILENAME), QFile::encodeName(soundFilePath));
+            QCOMPARE(properties.value(CA_PROP_APPLICATION_NAME), QByteArray("Test App"));
+            QCOMPARE(properties.value(CA_PROP_APPLICATION_ID), QByteArray("org.kde.test"));
+            QCOMPARE(properties.value(CA_PROP_CANBERRA_XDG_THEME_NAME), QByteArray("ocean"));
+            QCOMPARE(properties.value(CA_PROP_CANBERRA_CACHE_CONTROL), QByteArray("volatile"));
+            player.play(request);
+            QVERIFY(backend.entered.tryAcquire(1, 5000));
+            QCOMPARE(backend.created.load(), 1);
+        }
+        QCOMPARE(backend.destroyed.load(), 1);
+        QVERIFY(backend.correctThread);
+        QVERIFY(thread.isNull());
+    }
+
+    void recoversFromAllocationFailures_data()
+    {
+        QTest::addColumn<bool>("failContext");
+        QTest::newRow("context") << true;
+        QTest::newRow("properties") << false;
+    }
+
+    void recoversFromAllocationFailures()
+    {
+        QFETCH(bool, failContext);
+        {
+            CanberraSoundPlayer player;
+            backend.failContext = failContext;
+            backend.failProperties = !failContext;
+            QTest::ignoreMessage(QtWarningMsg,
+                                 QRegularExpression(failContext ? u"Failed to initialize canberra context for audio notification:.*"_s
+                                                                : u"Failed to create canberra properties for audio notification:.*"_s));
+            player.play({u"bell"_s, {}, {}, {}, u"ocean"_s});
+            QTRY_VERIFY(!backend.failContext && !backend.failProperties);
+            QCOMPARE(backend.played.load(), 0);
+            player.play({u"bell"_s, {}, {}, {}, u"ocean"_s});
+            QVERIFY(backend.entered.tryAcquire(1, 5000));
+        }
+        QCOMPARE(backend.created.load(), 1);
+        QCOMPARE(backend.destroyed.load(), 1);
+        QVERIFY(backend.correctThread);
+    }
+
+    void blockedBackendDoesNotBlockCallerOrShutdown()
+    {
+        backend.block = true;
+        auto player = std::make_unique<CanberraSoundPlayer>();
+        // Release even if an assertion fails, so the worker can clean up.
+        const auto release = qScopeGuard([] {
+            backend.unblock.release();
+        });
+        const CanberraSoundRequest request{u"bell"_s, {}, {}, {}, u"ocean"_s};
+        player->play(request);
+        QVERIFY(backend.entered.tryAcquire(1, 5000));
+        QPointer<QThread> thread = backend.workerThread;
+        bool timerFired = false;
+        QTimer::singleShot(0, this, [&timerFired] {
+            timerFired = true;
+        });
+        player->play(request);
+        QTRY_VERIFY(timerFired);
+        QCOMPARE(backend.played.load(), 1);
+
+        QElapsedTimer elapsed;
+        elapsed.start();
+        QTest::ignoreMessage(QtWarningMsg, "Canberra sound thread did not stop within 2s; leaving it to finish asynchronously.");
+        player.reset();
+        QVERIFY2(elapsed.elapsed() < 5000, "Destroying the player must not wait indefinitely for libcanberra");
+        QCOMPARE(backend.destroyed.load(), 0);
+        QVERIFY(thread);
+
+        backend.unblock.release();
+        QTRY_COMPARE(backend.destroyed.load(), 1);
+        QTRY_VERIFY(thread.isNull());
+        // The sound queued while the backend was blocked is discarded on shutdown.
+        QCOMPARE(backend.played.load(), 1);
+        QVERIFY(backend.correctThread);
+    }
+};
+
+QTEST_GUILESS_MAIN(CanberraSoundPlayerTest)
+
