+#include "canberrasoundplayer_p.h"
+
+#include <QFile>
+
+#include <canberra.h>
+
+#include "debug.h"
+
+using namespace Qt::StringLiterals;
+using namespace NotificationManager;
+
+namespace NotificationManager
+{
+class CanberraSoundWorker : public QObject
+{
+public:
+    ~CanberraSoundWorker() override
+    {
+        if (m_context) {
+            ca_context_destroy(m_context);
+        }
+    }
+
+    void play(const CanberraSoundRequest &request);
+
+private:
+    ca_context *m_context = nullptr;
+};
+}
+
+CanberraSoundPlayer::CanberraSoundPlayer(QObject *parent)
+    : QObject(parent)
+    , m_thread(new QThread)
+    , m_worker(new CanberraSoundWorker)
+{
+    m_thread->setObjectName(u"canberra-sound"_s);
+    m_worker->moveToThread(m_thread);
+    connect(m_thread, &QThread::finished, m_worker, &QObject::deleteLater);
+    connect(m_thread, &QThread::finished, m_thread, &QObject::deleteLater);
+    m_thread->start();
+}
+
+CanberraSoundPlayer::~CanberraSoundPlayer()
+{
+    m_thread->requestInterruption();
+    QMetaObject::invokeMethod(
+        m_worker,
+        [thread = m_thread] {
+            thread->quit();
+        },
+        Qt::QueuedConnection);
+
+    if (m_thread->wait(2000)) {
+        delete m_thread;
+    } else {
+        // The worker and thread own their remaining lifetime. If libcanberra
+        // recovers, the queued quit will finish the thread and delete both.
+        // Do not terminate a thread that may hold locks inside the audio library.
+        qCWarning(NOTIFICATIONMANAGER) << "Canberra sound thread did not stop within 2s; leaving it to finish asynchronously.";
+    }
+}
+
+void CanberraSoundPlayer::play(const CanberraSoundRequest &request)
+{
+    QMetaObject::invokeMethod(
+        m_worker,
+        [worker = m_worker, request] {
+            worker->play(request);
+        },
+        Qt::QueuedConnection);
+}
+
+void CanberraSoundWorker::play(const CanberraSoundRequest &request)
+{
+    Q_ASSERT(QThread::currentThread() == thread());
+
+    if (QThread::currentThread()->isInterruptionRequested()) {
+        return;
+    }
+
+    if (!m_context) {
+        const int ret = ca_context_create(&m_context);
+        if (ret != CA_SUCCESS) {
+            qCWarning(NOTIFICATIONMANAGER) << "Failed to initialize canberra context for audio notification:" << ca_strerror(ret);
+            m_context = nullptr;
+            return;
+        }
+    }
+
+    ca_proplist *props = nullptr;
+    const int propsRet = ca_proplist_create(&props);
+    if (propsRet != CA_SUCCESS) {
+        qCWarning(NOTIFICATIONMANAGER) << "Failed to create canberra properties for audio notification:" << ca_strerror(propsRet);
+        return;
+    }
+
+    if (!request.soundName.isEmpty()) {
+        ca_proplist_sets(props, CA_PROP_EVENT_ID, request.soundName.toLatin1().constData());
+    }
+    if (!request.soundFilePath.isEmpty()) {
+        ca_proplist_sets(props, CA_PROP_MEDIA_FILENAME, QFile::encodeName(request.soundFilePath).constData());
+    }
+    ca_proplist_sets(props, CA_PROP_APPLICATION_NAME, request.appName.toLatin1().constData());
+    ca_proplist_sets(props, CA_PROP_APPLICATION_ID, request.desktopFile.toLatin1().constData());
+    ca_proplist_sets(props, CA_PROP_CANBERRA_XDG_THEME_NAME, request.soundTheme.toLatin1().constData());
+    // volatile: drop cache under pressure / after some time
+    ca_proplist_sets(props, CA_PROP_CANBERRA_CACHE_CONTROL, "volatile");
+
+    const int ret = ca_context_play_full(m_context, 0, props, nullptr, nullptr);
+
+    ca_proplist_destroy(props);
+
+    if (ret != CA_SUCCESS) {
+        qCWarning(NOTIFICATIONMANAGER) << "Failed to play sound" << request.soundName << "with canberra:" << ca_strerror(ret);
+    }
+}
