+#pragma once
+
+#include <QObject>
+#include <QString>
+#include <QThread>
+
+namespace NotificationManager
+{
+
+class CanberraSoundWorker;
+
+struct CanberraSoundRequest {
+    QString soundName;
+    QString soundFilePath;
+    QString appName;
+    QString desktopFile;
+    QString soundTheme;
+};
+
+// Runs libcanberra on a dedicated worker thread so a wedged audio backend
+// can't block the caller. See KDE bug 511472 for the failure mode.
+// The player remains on the caller thread; only the worker calls libcanberra.
+class CanberraSoundPlayer : public QObject
+{
+    Q_OBJECT
+public:
+    explicit CanberraSoundPlayer(QObject *parent = nullptr);
+    ~CanberraSoundPlayer() override;
+
+    // Queues the sound on the worker thread and returns immediately.
+    void play(const CanberraSoundRequest &request);
+
+private:
+    QThread *m_thread;
+    CanberraSoundWorker *m_worker;
+};
+
+}
